func ticketNodeToData(n *TicketNode) map[string]interface{} {
	data := map[string]interface{}{
		"slug":     n.Slug,
		"title":    n.Title,
		"status":   n.Status,
		"started":  n.Created,
		"finished": n.Finished,
		"prompt":   n.Description,
		"summary":  n.Summary,
	}
	if n.URI != "" {
		yIdx := strings.Index(n.URI, "repo://y/")
		if yIdx >= 0 {
			rest := strings.TrimPrefix(n.URI[yIdx:], "repo://y/")
			parts := strings.Split(rest, "/")
			if len(parts) >= 6 {
				if y, err := strconv.Atoi(parts[0]); err == nil {
					data["year"] = float64(y)
				}
				if m, err := strconv.Atoi(parts[2]); err == nil {
					data["month"] = float64(m)
				}
				if d, err := strconv.Atoi(parts[4]); err == nil {
					data["day"] = float64(d)
				}
			}
		}
	}
	return data
}

